const normalizeImageUrl = u => {
  const s=String(u||'').trim()
  if(!s)return ''
  if(/^https?:\/\//i.test(s) || s.startsWith('data:') || s.startsWith('blob:')) return s
  return s.startsWith('/') ? s : `/${s}`
}
