function staffPermissions(){return Array.isArray(profile?.staff_permissions)?profile.staff_permissions.map(x=>String(x).toLowerCase()):[]}
function isAdmin(){const r=String(profile?.role||'').toLowerCase();return ['admin','manager','product_manager','order_manager','marketing_manager','inventory_manager','staff'].includes(r) && profile?.is_blocked!==true}
function can(area){const r=String(profile?.role||'').toLowerCase();if(profile?.is_blocked===true)return false;if(r==='admin')return true;if(r==='manager')return ['products','categories','banners','offers','orders','customers','inventory','marketing','settings','audit'].includes(area);if(r==='product_manager')return ['products','categories','banners','offers'].includes(area);if(r==='order_manager')return ['orders','customers'].includes(area);if(r==='marketing_manager')return ['banners','offers','marketing'].includes(area);if(r==='inventory_manager')return area==='inventory';if(area==='staff')return r==='admin';if(area==='audit')return r==='admin';if(r==='staff'){if(area==='products')return false;return staffPermissions().includes(area)}return false}
function go(v){if(v==='admin')return; if(view!==v)viewStack.push(view);view=v;modal=null;render()}
function goBack(){if(modal){modal=null;render();return}view=viewStack.length?viewStack.pop():'shop';render()}

async function loadPublic(){
  // Always keep the public catalog available. Supabase is used when reachable;
  // the bundled catalog is a safe fallback so a transient API/RLS/config issue
  // can never turn the storefront into an empty page.
  categories = Array.isArray(catalogFallback.categories) ? catalogFallback.categories : []
  products = Array.isArray(catalogFallback.products) ? catalogFallback.products : []
  banners = []
  offers = []
  settings = {store_name_ar:'MartLinker',store_name_fr:'MartLinker',tagline_ar:'متجر DXN في موريتانيا',tagline_fr:'Boutique DXN en Mauritanie',delivery_fee:0,branch_name_ar:'فرع DXN كرفور مدريد',branch_name_fr:'Point de vente DXN Carrefour Madrid',branch_phone:'+222 20103010',branch_whatsapp:'22220103010'}
  if(!supabase) return
  try {
    const [s,c,p,b,o] = await Promise.all([
      supabase.from('site_settings').select('*').limit(1).maybeSingle(),
      supabase.from('categories').select('*').order('sort_order',{ascending:true}),
      supabase.from('products').select('*').eq('is_active',true).order('sort_order',{ascending:true}),
      supabase.from('banners').select('*').eq('is_active',true).order('sort_order',{ascending:true}),
      supabase.from('offers').select('*').eq('is_active',true)
    ])
    if(!s.error && s.data) settings={...settings,...s.data}
    if(!c.error && Array.isArray(c.data) && c.data.length) categories=c.data
    if(!p.error && Array.isArray(p.data) && p.data.length) products=p.data
    if(!b.error && Array.isArray(b.data)) banners=b.data
    if(!o.error && Array.isArray(o.data)) offers=o.data
    const validIds=new Set(products.map(p=>p.id))
    const nextCart=cart.filter(x=>validIds.has(x.id)).map(x=>({...x,qty:Math.min(Math.max(1,Number(x.qty||1)),Math.max(1,Number(products.find(p=>p.id===x.id)?.stock||1)))}))
    if(JSON.stringify(nextCart)!==JSON.stringify(cart)){cart=nextCart;saveCart()}
  } catch (err) {
    console.warn('Supabase public read failed; using bundled catalog.', err)
  }
}
async function syncSession(nextSession){
  session=nextSession||null
  profile=null
  if(session){
    const p=await supabase.from('profiles').select('*').eq('id',session.user.id).maybeSingle()
    profile=p.data||{id:session.user.id,email:session.user.email,full_name:session.user.user_metadata?.full_name,whatsapp:session.user.user_metadata?.whatsapp,role:'customer',is_blocked:false}
    const sr=await supabase.from('staff').select('permissions,is_active').eq('user_id',session.user.id).maybeSingle()
    profile.staff_permissions=sr.data?.is_active===false?[]:(Array.isArray(sr.data?.permissions)?sr.data.permissions:[])
  }
}
async function loadSession(){
  if(!supabase)return
  const r=await supabase.auth.getSession()
  await syncSession(r.data.session||null)
}

function waNumber(value){
  let n=String(value||'').replace(/\D/g,'');
  if(n.startsWith('00')) n=n.slice(2);
  if(n.length===8) n='222'+n;
  return n;
}
function waOrderLink(o){
  const n=waNumber(o?.whatsapp);
  if(!n)return '';
  const id=String(o?.id||'').slice(0,8);
  const status=String(o?.status||'pending');
  const msg=lang==='fr'
    ? `Bonjour ${o?.full_name||''}, concernant votre commande #${id}, son statut est: ${status}. Nous vous contacterons si nécessaire.`
    : `السلام عليكم ${o?.full_name||''}، بخصوص طلبيتكم #${id}، حالتها الحالية: ${status}. سنتواصل معكم عند الحاجة.`;
  return `https://wa.me/${n}?text=${encodeURIComponent(msg)}`;
}
