function authForm(mode){return `<div class="authHero"><div class="authMark">ML</div><div><h2>${mode==='login'?t('login'):t('signup')}</h2><p>${mode==='signup'?(lang==='ar'?'أنشئ حسابك باستخدام Gmail فقط وسنرسل لك رمز OTP.':'Créez votre compte avec Gmail uniquement et recevez un code OTP.'):(lang==='ar'?'تجربة شراء بسيطة وآمنة في MartLinker':'Une expérience d’achat simple et sécurisée sur MartLinker')}</p></div></div><form class="form authForm" onsubmit="window.${mode==='login'?'login':'signup'}(event)"><label>${t('email')}<input name="email" type="email" autocomplete="email" placeholder="${mode==='signup'?'name@gmail.com':t('email')}" required></label>${mode==='login'?`<label>${t('password')}<input name="password" type="password" autocomplete="current-password" minlength="6" placeholder="${t('password')}" required></label>`:''}<button class="primary authSubmit">${mode==='login'?t('signIn'):(lang==='ar'?'إرسال رمز OTP':'Envoyer le code OTP')}</button><button type="button" class="secondary authGoogleBtn" onclick="window.googleLogin()"><span>G</span><span>${lang==='ar'?'المتابعة باستخدام Google':'Continuer avec Google'}</span></button>${mode==='login'?`<button type="button" class="authSwitch" onclick="window.magicLoginMode()">${lang==='ar'?'🔐 الدخول بدون كلمة مرور':'🔐 Connexion sans mot de passe'}</button><button type="button" class="authSwitch" onclick="window.forgotPassword()">${lang==='ar'?'نسيت كلمة المرور؟':'Mot de passe oublié ?'}</button>`:''}<button type="button" class="authSwitch" onclick="window.authMode('${mode==='login'?'signup':'login'}')">${mode==='login'?(lang==='ar'?'إنشاء حساب جديد':'Créer un compte'):(lang==='ar'?'لدي حساب بالفعل':'J’ai déjà un compte')}</button></form>`}
